import { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./dashboard.css";

export default function Dashboard() {
  const navigate = useNavigate();

  const user = JSON.parse(localStorage.getItem("user"));
  const [users, setUsers] = useState(JSON.parse(localStorage.getItem("users")) || []);
  const [courses, setCourses] = useState(JSON.parse(localStorage.getItem("courses")) || []);

  if (!user) {
    navigate("/login");
    return null;
  }

  // DELETE USER
  const deleteUser = (id) => {
    const updated = users.filter(u => u.id !== id);
    setUsers(updated);
    localStorage.setItem("users", JSON.stringify(updated));
  };

  // DELETE COURSE
  const deleteCourse = (id) => {
    const updated = courses.filter(c => c.id !== id);
    setCourses(updated);
    localStorage.setItem("courses", JSON.stringify(updated));
  };

  return (
    <div className="dashboard-container">

      {/* HEADER */}
      <div className="header">
        <h1>🎯 RBAC ADMIN DASHBOARD</h1>
        <h2>Welcome, {user.name}</h2>
        <p>{user.email}</p>
        <span className="role">{user.role}</span>
      </div>

      {/* STATS */}
      <div className="stats">

        <div className="stat">
          <h3>{users.length}</h3>
          <p>Total Users</p>
        </div>

        <div className="stat">
          <h3>{users.filter(u => u.role === "Student").length}</h3>
          <p>Students</p>
        </div>

        <div className="stat">
          <h3>{users.filter(u => u.role === "Instructor").length}</h3>
          <p>Instructors</p>
        </div>

        <div className="stat">
          <h3>{courses.length}</h3>
          <p>Courses</p>
        </div>

      </div>

      {/* USERS TABLE */}
      <h2 className="title">👥 Users Management</h2>

      <div className="table">
        {users.map(u => (
          <div className="row" key={u.id}>
            <span>{u.name}</span>
            <span>{u.email}</span>
            <span>{u.role}</span>

            <button onClick={() => deleteUser(u.id)}>Delete</button>
          </div>
        ))}
      </div>

      {/* COURSES TABLE */}
      <h2 className="title">📚 Courses Management</h2>

      <div className="table">
        {courses.map(c => (
          <div className="row" key={c.id}>
            <span>{c.name}</span>
            <span>{c.instructor}</span>

            <button onClick={() => deleteCourse(c.id)}>Delete</button>
          </div>
        ))}
      </div>

    </div>
  );
}
